<?php
namespace App\Modules\Sales\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Identity\Application\CreateAuthorizationRequest;use App\Modules\Sales\Domain\Models\Sale;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class RequestSaleAuthorizationController extends Controller {public function __invoke(Request $request,Sale $sale,CreateAuthorizationRequest $action):RedirectResponse{abort_unless($request->user()->hasPermission('authorizations.request'),403);$d=$request->validate(['type'=>['required',Rule::in(['price','inventory','credit'])],'reason'=>['required','string','max:2000']]);[$operation,$permission]=match($d['type']){'price'=>['sales.price-below-minimum','prices.authorize-below-minimum'],'inventory'=>['sales.inventory-negative','inventory.authorize-negative'],'credit'=>['sales.credit-limit','sales.authorize-credit']};$action->execute($operation,$permission,$sale,$request->user(),$d['reason']);return back()->with('success','Autorización solicitada.');}}
